      SUBROUTINE DSROTRCC     CALCULATES THE PARTIAL DERIVATIVES OF THE FIRST-ORDER MATRIXC     ELEMENTS WITH RESPECT TO THE TILT (ROLL).CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'R.CIN'C---------------------------------------------------------------      DO 20 J = 1, 6      DO 20 K = 1, 6      RV(J,K) = R(J,K)   20 CONTINUEC      DO 50 K = 1, 6      RV1K = - RV(3,K)      RV2K = - RV(4,K)      RV(3,K) = RV(1,K)      RV(4,K) = RV(2,K)      RV(1,K) = RV1K      RV(2,K) = RV2K   50 CONTINUEC      DO 55 J = 1, 6      RVJ1 = - RV(J,3)      RVJ2 = - RV(J,4)      RV(J,3) = RV(J,1)      RV(J,4) = RV(J,2)      RV(J,1) = RVJ1      RV(J,2) = RVJ2   55 CONTINUEC      DPU = DPARM*UNITI(13)      DO 60 J = 1, 6      DO 60 K = 1, 6      RV(J,K) = RV(J,K)*DPU   60 CONTINUEC      RETURN      END